void USB_SetSuspendM(void)
{
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) &= ~(1<<10);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) &= ~(1<<26);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB2_CONFIG) &= ~(1<<26);
}

void USB_ClrSuspendM(void)
{
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) |= (1<<10);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) |= (1<<26);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB2_CONFIG) |= (1<<26);
}

void USB_SetPhyReset(void)
{
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) |= (1<<12);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) |= (1<<28);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB2_CONFIG) |= (1<<28);
}

void USB_ClrPhyReset(void)
{
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) &= ~(1<<12);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB1_CONFIG) &= ~(1<<28);
	*(volatile unsigned int *)(CONFIG_BASE_MMU+CONFIG_USB2_CONFIG) &= ~(1<<28);
}

