static void usb_phy_init_pegasus(void)
{
#define PEGASUS_CONFIG_BASE_PORT0 (GX_REG_VIRTUAL_BASE1 + 0x04340000)
#define PEGASUS_CONFIG_BASE_PORT1 (GX_REG_VIRTUAL_BASE1 + 0x04340400)

	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT0 + 0x00) = 0x1c;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT0 + 0x08) = 0x7c;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT0 + 0x14) = 0xac;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT0 + 0x18) = 0x05;

	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT1 + 0x00) = 0x1c;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT1 + 0x08) = 0x7c;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT1 + 0x14) = 0xac;
	*(volatile unsigned int*)(PEGASUS_CONFIG_BASE_PORT1 + 0x18) = 0x05;

#ifdef CONFIG_USB_EYE_DIAGRAM_TEST
	int i = 0;
	int total_num = 0;
	total_num = 0x20;
	for (i = 0; i <= total_num; i+=4) {
		if ((i % 16) == 0)
			printf("\n0x%x: ", PEGASUS_CONFIG_BASE_PORT0 + i);
		printf("0x%08x ", *(volatile unsigned int *)(PEGASUS_CONFIG_BASE_PORT0 + i));
	}
	printf("\n");

	for (i = 0; i <= total_num; i+=4) {
		if ((i % 16) == 0)
			printf("\n0x%x: ", PEGASUS_CONFIG_BASE_PORT1 + i);
		printf("0x%08x ", *(volatile unsigned int *)(PEGASUS_CONFIG_BASE_PORT1 + i));
	}
	printf("\n");
#endif

	return ;
}

void USB_Init(void)
{
	/* usb phy */
	if (REG_CHIP_6605S_PROBE != 0)
		usb_phy_init_pegasus();
	else
		usb_phy_init_6605s();

	/* clock */
#if 1
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<24);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (0x3<<24); //div to 148.5
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<30); //load en
#endif
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= 1|(1<<1)|(1<<2)|(1<<3)|(1<<4);

	/* usb phy port */
#if 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_USB_CONFIG) |= (1<<25)|(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_USB3_CONFIG) |= (1<<25);
#else
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_USB_CONFIG)  |= (1<<25) | (1<<31) | (0x20<<8) | (0x20<<20) | (0x20<<26) | (0xf<<16);
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_USB3_CONFIG) |= (1<<25) | (0x20<<20);
#endif

#ifdef ENABLE_SECURE_ALIGN
	*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_USB3_CONFIG) |= 1; //set usb port 32 bit align
#endif

	USB_SetSuspendM();
	USB_SetPhyReset();
	USB_ClrPhyReset();
	USB_ClrSuspendM();
	USB_SetSuspendM();
	USB_SetPhyReset();
	USB_ClrPhyReset();
}

/* only for hardware usb test */
void EHCI_Test(void)
{
#define EHCI_OPBASE	(REG_BASE_USB_EHCI+0x10)

#define EHCI_OPREG_USBCMD		(EHCI_OPBASE+0x0)
#define EHCI_OPREG_USBSTS		(EHCI_OPBASE+0x4)
#define EHCI_OPREG_USBINTR		(EHCI_OPBASE+0x8)
#define EHCI_OPREG_FRINDEX		(EHCI_OPBASE+0xc)
#define EHCI_OPREG_CTRLDSSEGMENT	(EHCI_OPBASE+0x10)
#define EHCI_OPREG_PERIODICLISTBASE	(EHCI_OPBASE+0x14)
#define EHCI_OPREG_ASYNCLISTADDR	(EHCI_OPBASE+0x18)
#define EHCI_OPREG_CONFIGFLAG		(EHCI_OPBASE+0x40)
#define EHCI_OPREG_PORTSC1		(EHCI_OPBASE+0x44)
#define EHCI_OPREG_PORTSC2		(EHCI_OPBASE+0x48)
#define EHCI_OPREG_PORTSC3		(EHCI_OPBASE+0x4c)
	printf("enter echi test, hardware engineer can test after this printf.\n");
	*(volatile unsigned int *)(EHCI_OPREG_USBCMD) &= ~((1<<5)|(1<<4));
	*(volatile unsigned int *)(EHCI_OPREG_PORTSC1) |= (1<<7);
	*(volatile unsigned int *)(EHCI_OPREG_USBCMD) &= ~0x1;	//ehci stop
	while(((*(volatile unsigned int *)(EHCI_OPREG_USBSTS)) & (1<<12)) == 0);
	*(volatile unsigned int *)(EHCI_OPREG_PORTSC1) |= (4<<16);
	*(volatile unsigned int *)(EHCI_OPREG_PORTSC2) |= (4<<16);
	*(volatile unsigned int *)(EHCI_OPREG_PORTSC3) |= (4<<16);
	while(1);
}

void close_macrovision(void)
{
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL0) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL1) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL2) = 0;
	*(volatile unsigned int*)(GX_REG_VIRTUAL_BASE1 + MACROVISION_CTRL3) = 0;
}

static struct pll_dto {
	unsigned int dto;
	unsigned int div;
	unsigned int value;
} dto_table[] = {
	{7  , 0x08000000 , 1 << 16} ,  // GA 		148.5MHZ
	{8  , 0x091ab875 , 1 << 17} ,  // DemuxSys 	169MHz
	{9  , 0x05d1745d , 1 << 18} ,  // DemuxStc 	108MHz
	{3  , 0x0a9ce01c , 1 << 12} ,  // Video  	197Mhz
	{4  , 0x08000000 , 1 << 13} ,  // JPEG	 	148.5MHZ
	{6  , 0x0cc48677 , 1 << 15} ,  // Audio decoder 240MHZ
	{1  , 0x04a7904a , 1 << 1} ,   // Audio i2s	86.4MHz
	{2  , 0x04a7904a , 1 << 1} ,   // Audio spdif	86.4MHz
	{5  , 0x08000000 , 1 << 14} ,  // PP		148.5MHZ
};

void gx_setup_pll_full_controller(void)
{
	int i;
	//unsigned int adc_rdy;

	for (i=0; i < sizeof(dto_table) / sizeof(struct pll_dto); i++) {
		if (dto_table[i].dto != 0)
			DTO_Config(dto_table[i].dto, dto_table[i].div, 1);
		*(volatile unsigned int*)(CONFIG_BASE_MMU + CONFIG_SOURCE_SEL) |= dto_table[i].value;
	}

	/* pegasus smartcard clock select 198MHz */
	if (REG_CHIP_6605S_PROBE != 0) {
		DTO_Config(13, 0x0aaaaaaa, 1); //config apb4 dto clock to 198MHz
		*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<23); //apb4 clock source select 198MHz
		*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<22); //smartcard clock source select apb4 clock
	}

//tmp macro, will delete later
#define CPU_FREQ	1
#define UART_CLOCK 1
#define AUDIO_USE_DVB 0
#define PCM_CLOCK_OPEN 0
#define USB_DEFINE   0

#if 0
//audio decoder
#if AUDIO_USE_DVB
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_DTO6_CONFIG) &= ~(1<<31);	//DTO 31 set 0, use the DVB clock
#else
	DTO_Config(6, 0x0CC48677);//240M // AUDIO USE DTO, USE 240M
#endif
#endif

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<15);

	//clock auido
	//clock audio clock_audio_lodec
	// div
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<23);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (7<<23); //div/8分频、400/8=50M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<30); //load end
	//   source
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<0); //sel to pll divm clock

	//DVB DIV
	//clock audio clock_audio_lodec
	// div
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<7);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<7); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<0);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (19<<0); //div//24分频、、999/20=49.95M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<6);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<6); //load end
	//select form PLL_DTO  DTO or from the DVB div
	//*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) &= ~(1<<3); //from PLL_DTO DTO
	//*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<3);  //from PLL_DVB DIV

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<2); // SPD clok xtal to pll

	//PCM clock
#if PCM_CLOCK_OPEN
	//gate the mac
	//*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_MPEG_HOT_RST2_1SET) |= (1<<6);//gate
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_MPEG_HOT_RST2_1CLR) |= (1<<6);//open
#endif
	//end audio set

	// begin the video piex clok
	//////pixel CLOCK div

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_MPEG_CLK_INHIBIT_NORM) |= 1 <<30;
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<6);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<6); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<0);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (0x7<<0); //div to 148.5
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<7);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<7); //load en

	// even div clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<20);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<20); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(0x3f<<12);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (0x2a<<12); //div to 27
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(1<<19);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (1<<19); //load en
	//source
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<5); //from xtal to pll clock

	//SVPU clock source
#ifdef CONFIG_24M_XTAL
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<6); //SVPU clock from DTO
#else
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) &= ~(1<<6); //SVPU clock from xtal
#endif
	//div the pixel clcok to div2
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(0x7<<8);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (0x5<<8);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) &= ~(0x1<<11);   //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG) |= (0x1<<11);


	//div the pixel1 clcok to div2
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(0x3<<26);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x3<<26);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(0x1<<25);   //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<25);

	//HDMI  clock_hdmi_icec clock select
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<5);
	//dcs pixel pixdel double hdmi hdmi phy hdmi icec hdmi sfr
	//end the pixel clcok

	// video dac clock

	// dac clock come from pixel doule or ivnv of double
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(0x1<<6);//use the inv of the pixel doubleclock
	///// *(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<6);  //use the pixel double clcok
	// dac clock come from pixel1 doule or ivnv of double
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(0x1<<6);//use the inv of the pixel doubleclock
	//*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<6);  //use the pixel double clcok
	//dac1 0 from pixel 1 from pixel1
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<8); // Select dac clock1 from vpu or svpu. 0 from vpu; 1 from svpu
	//dac gain control
#ifdef CONFIG_ENABLE_GX_OTP
	unsigned char otp_data = 0x0;
	gx_otp_read(0x103, 1, &otp_data);
	if (otp_data >> 7) {
		otp_data = otp_data & 0x3f;
		*(volatile unsigned int*)(DAC_GAIN_CONTROL) =
			((otp_data << 24) | (otp_data << 16) | (otp_data << 8) | (otp_data));
	} else
		*(volatile unsigned int*)(DAC_GAIN_CONTROL) = 0x23232323;
#else
	printf("\n\nerror : configure DAC must set ENABLE_GX_OTP = y !\n\n");
	while(1);
#endif
	//end the video dac

	//TS
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<11);//ts1

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<14);//ts1

#if USB_DEFINE
	//use div 99 to get the clock , not need set
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<0); //usb phy generate //12M
	// usb mac clock
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<1); //usb mac 60M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<2); //usb mac 60M
	// usb 48M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<3); //usb mac 48M
	//usb 12M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<31);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<31); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<24);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (0x3<<24); //div to 148.5
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<30); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<4); //from xtal to phy
#endif

#if 1	//DVB CONFIG

	//ts base clock

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<15);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<15); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(0x3f<<8);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (3<<8); //div to 44 27M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) &= ~(1<<14);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG3) |= (1<<14); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<21); // select from not xtal
	//end ts base

	// PLL clcok select 0 come from DVB 1, come from the DTO
	//come from the DVB
	//*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) &= ~(1<<20); // select from not xtal
	// come from the DTO
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (1<<20); // select from DTO

#ifdef DVB_CHANNEL_S2
	// DIV for dvbs 1
	// to 118.8 //dvb 1188 div 118.8
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<12);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<12); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<4);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (9<<4); //div to 44
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<11);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<11); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<30); // select from not xtal

	//to 132M//DVb 1188 div9  to132
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<21);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<21); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<13);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (8<<13); //div to 44
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<20);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<20); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<29); // select from not xtal

	//When DVBS use the DAC clock for 237.6
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<30);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<30); //rst
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(0x3f<<22);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (4<<22); //div to 44 27M
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) &= ~(1<<29);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_CLOCK_DIV_CONFIG2) |= (1<<29); //load en

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (1<<27); // select from not xtal to div

	//adc clock
	// dvb module adc clok
	// to adc clock inv
	// *(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<10); // select 00 doube of dvbs clok
	//not inv
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL2) |= (0x1<<10); //

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_SOURCE_SEL) |= (0x1<<31); // xtal to PLL adc
	//adc set

	//set the  fsctrl
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &= ~(0xff<<10); // fsctrl 000is 1x 11111111 = 1.996x
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |= (0x80<<10); // fsctrl 000is 1x 11111111 = 1.996x
	//bctrl 00110
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &= ~(0x1f<<2);
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |= (0x6<<2); ///70%

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &= ~(0x1f<<24); // set i2c address
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |=  (0x1d<<24); // set i2c address //1d << 2 address is 74
	//set the scl and sda is high
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |=  (0x7<<29); // set scl and sdi and i2c resetz go high

	// when power down . adc is in power down  mode set opm =00;

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &= ~((0x3<<18) | (0x1<<8) ); // adc in power down mode endacr is 0
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |= (1<<8); // endcr disable the duty cycle restorer

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &=  ~(0x3<<22); // use_prev_f is zero ,powerup need the use_prev_f, startcal set zero, power auto starcal

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) &= ~(0x1<<29); // i2c resetz set low keep at leas 4ns
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |=  (0x1<<29); // i2c resetz set hihgh no is

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |=  (0x3<<18); // i2c resetz set hihgh no is
	// set to the normal mode
	//do {
	//	adc_rdy = (*(volatile unsigned int*)(CONFIG_BASE_MMU+STATE_ADC))& 0x2 ; // [1] bit is adcrdy
	//} while (!(adc_rdy & 0x2));
	// set the port
	// DVBS set the duble I and q

	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_ADC) |=  (0x1<<7) |(0x1<<20) ; // i2c resetz set hihgh no is
	//end

#endif

	//video adc
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_DAC) &= ~(0x1<<0);	//enextref set zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_DAC) |= (0x1<<1);	//envbg set high
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_DAC) &= ~(0x7<<4);	//enctr set zero
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_DAC) &= ~(0xf<<8);	//ensc set zero
#endif

	//modify spdif driver strength, 0xa030aa04[28:27]: 00-6.6mA, 01-13.3mA, [10-19.9mA], 11-26.5mA
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_IO_DRIVE_CTL1) |= 1 << 28;
	*(volatile unsigned int*)(CONFIG_BASE_MMU+CONFIG_IO_DRIVE_CTL1) &= ~(1 << 27);

	close_macrovision();
	USB_Init();
#ifdef CONFIG_USB_EYE_DIAGRAM_TEST
	EHCI_Test();
#endif

	/* 芯片有个陈旧的tlb模块,会检查各模块的ddr申请,如果申请地址在0x010000000-0x0fffffff范围内,会粗暴断联axi申请,从而导致模块卡死
	 * 配置0xa030a164 = 7可以删除该tlb模块
	 * */
	*(volatile unsigned int *)0xa030a164 = 7;
}

